PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://lbrontek.github.io/refinements/1.1/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone ?rdfs_label ?sensor ?ts_id
WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?rdfs_label }
  ?sensor a brick:ElectricPowerSensor ;
          brick:hasSubComponent ?zone .
  OPTIONAL { ref:ts ?sensor ?ts_id }
}
LIMIT 200

SELECT ?sensor ?rel ?zone ?zlabel WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  OPTIONAL { ?sensor brick:isRelatedTo ?rel }
  OPTIONAL { ?zoneref brick:refersTo ?zone }
  ?zone brick:hasLabel ?zlabel .
}
LIMIT 20

SELECT ?sensor ?p (STR(?o) AS ?o) WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor ?p ?o .
  FILTER (STR(?p) != "http://qudt.org/schema/qudt/hasQuantityKind")
}
LIMIT 200

SELECT ?zone ?label WHERE {
  ?zone rdfs:label ?label .
  FILTER (CONTAINS(LCASE(?label), "basement") || CONTAINS(LCASE(?label), "perimeter"))
}
LIMIT 200

SELECT ?sensor ?label ?tsid WHERE {
  ?sensor a brick:Electric_Power_Sensor ;
          brick:isPointOf ?zone .
  ?zone a brick:HVAC_Zone .
  ?zone rdfs:label ?zlabel .
  ?sensor rdfs:label ?label .
  ?sensor ref:hasTimeseriesId ?tsid .
  FILTER (?zlabel IN ("Basement", "Perimeter_top_ZN_2"))
}

SELECT ?sensor ?slab ?zonel WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor brick:isPointOf ?zone .
  ?zone a brick:HVAC_Zone .
  OPTIONAL { ?zone rdfs:label ?zonel }
  OPTIONAL { ?sensor rdfs:label ?slab }
}

